/* --- Operations Dashboard — Dark Theme --- */
/* --- Dashboard Shell --- */
.ops-dashboard {
 min-height: 100vh;
 background: #0a0e14;
 color: #e2e8f0;
 font-family: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI", sans-serif;
}

.ops-dashboard__content {
 padding: 24px;
 max-width: 1440px;
 margin: 0 auto;
}

/* --- Page Header --- */
.ops-page-header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 margin-bottom: 24px;
}

.ops-page-header__title {
 font-size: 28px;
 font-weight: 700;
 margin: 0 0 4px 0;
 color: #e2e8f0;
}

.ops-page-header__subtitle {
 font-size: 14px;
 color: #64748b;
 margin: 0;
}

.ops-page-header__live-pill {
 display: inline-flex;
 align-items: center;
 gap: 8px;
 font-size: 12px;
 color: #94a3b8;
 background: rgba(34, 197, 94, 0.06);
 border: 1px solid rgba(34, 197, 94, 0.2);
 border-radius: 20px;
 padding: 5px 14px;
}

.ops-page-header__live-dot {
 width: 7px;
 height: 7px;
 border-radius: 50%;
 background: #22c55e;
 animation: ops-pulse-glow 2s infinite;
}

@keyframes ops-pulse-glow {
 0%, 100% {
 opacity: 1;
 }
 50% {
 opacity: 0.4;
 }
}
/* --- KPI Row --- */
.ops-kpi-row {
 display: grid;
 grid-template-columns: repeat(5, 1fr);
 gap: 16px;
 margin-bottom: 24px;
}

/* --- KPI Card --- */
.ops-kpi-card {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 20px;
 display: flex;
 flex-direction: column;
}

.ops-kpi-card--red {
 background: rgba(239, 68, 68, 0.04);
 border-color: rgba(239, 68, 68, 0.25);
}

.ops-kpi-card__label {
 display: flex;
 align-items: center;
 gap: 6px;
 font-size: 11px;
 font-weight: 600;
 color: #64748b;
 text-transform: uppercase;
 letter-spacing: 0.6px;
 margin-bottom: 12px;
}

.ops-kpi-card__label-icon {
 display: inline-flex;
 color: #ef4444;
}

.ops-kpi-card__value {
 font-size: 28px;
 font-weight: 700;
 color: #e2e8f0;
 font-variant-numeric: tabular-nums;
 margin-bottom: auto;
 padding-bottom: 12px;
}

.ops-kpi-card__value--red {
 color: #ef4444;
}

.ops-kpi-card__caption {
 font-size: 11px;
 color: #64748b;
 margin: 0;
 line-height: 1.5;
}

/* --- Charts Row --- */
.ops-charts-row {
 display: grid;
 grid-template-columns: repeat(3, 1fr);
 gap: 16px;
 margin-bottom: 24px;
}

/* --- Generic Card --- */
.ops-card {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 24px;
}

.ops-card__header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 margin-bottom: 20px;
}

.ops-card__title {
 font-size: 15px;
 font-weight: 600;
 color: #e2e8f0;
 margin: 0 0 4px 0;
}

.ops-card__subtitle {
 font-size: 12px;
 color: #64748b;
 margin: 0;
}

/* --- Donut Chart --- */
.ops-donut {
 display: flex;
 align-items: center;
 gap: 24px;
}

.ops-donut__legend {
 display: flex;
 flex-direction: column;
 gap: 10px;
}

.ops-donut__legend-item {
 display: flex;
 align-items: center;
 gap: 8px;
 font-size: 12px;
 color: #94a3b8;
}

.ops-donut__legend-dot {
 width: 10px;
 height: 10px;
 border-radius: 50%;
 flex-shrink: 0;
}

.ops-donut__legend-value {
 color: #64748b;
 margin-left: 4px;
}

/* --- Horizontal Bar Chart --- */
.ops-hbar {
 display: flex;
 flex-direction: column;
 gap: 14px;
}

.ops-hbar__row {
 display: flex;
 align-items: center;
 gap: 12px;
}

.ops-hbar__label {
 font-size: 11px;
 color: #94a3b8;
 width: 110px;
 flex-shrink: 0;
 text-align: right;
}

.ops-hbar__track {
 flex: 1;
 height: 18px;
 background: rgba(59, 130, 246, 0.06);
 border-radius: 3px;
 position: relative;
}

.ops-hbar__fill {
 height: 100%;
 background: #3b82f6;
 border-radius: 3px;
 transition: width 0.3s ease;
}

.ops-hbar__value {
 font-size: 10px;
 color: #64748b;
 width: 32px;
 text-align: right;
 flex-shrink: 0;
 font-variant-numeric: tabular-nums;
}

.ops-hbar__axis {
 display: flex;
 justify-content: space-between;
 padding-left: 122px;
 padding-right: 44px;
 margin-top: 6px;
}

.ops-hbar__axis-label {
 font-size: 10px;
 color: #475569;
}

/* --- Vertical Bar Chart --- */
.ops-vbar {
 display: flex;
 gap: 8px;
 height: 200px;
}

.ops-vbar__y-axis {
 display: flex;
 flex-direction: column;
 justify-content: space-between;
 padding: 0 4px 24px 0;
}

.ops-vbar__y-label {
 font-size: 10px;
 color: #475569;
 text-align: right;
 width: 28px;
}

.ops-vbar__bars {
 display: flex;
 flex: 1;
 align-items: flex-end;
 gap: 12px;
 padding-bottom: 24px;
 border-bottom: 1px solid #1a2035;
}

.ops-vbar__col {
 flex: 1;
 display: flex;
 flex-direction: column;
 align-items: center;
 height: 100%;
}

.ops-vbar__bar-wrap {
 flex: 1;
 width: 100%;
 display: flex;
 align-items: flex-end;
 justify-content: center;
}

.ops-vbar__bar {
 width: 60%;
 background: #3b82f6;
 border-radius: 3px 3px 0 0;
 min-height: 4px;
 transition: background 0.12s ease;
}

.ops-vbar__bar:hover {
 background: #60a5fa;
}

.ops-vbar__x-label {
 font-size: 9px;
 color: #475569;
 margin-top: 8px;
 text-align: center;
 white-space: nowrap;
}

/* --- Live Queue Section --- */
.ops-queue {
 background: #111621;
 border: 1px solid #1a2035;
 border-radius: 12px;
 padding: 24px;
}

.ops-queue__header {
 display: flex;
 align-items: flex-start;
 justify-content: space-between;
 margin-bottom: 16px;
}

.ops-queue__title {
 font-size: 15px;
 font-weight: 600;
 color: #e2e8f0;
 margin: 0 0 4px 0;
}

.ops-queue__subtitle {
 font-size: 12px;
 color: #64748b;
 margin: 0;
}

.ops-queue__badge {
 font-size: 11px;
 font-weight: 600;
 padding: 4px 10px;
 border-radius: 6px;
 color: #f59e0b;
 background: rgba(245, 158, 11, 0.08);
 border: 1px solid rgba(245, 158, 11, 0.2);
 white-space: nowrap;
 flex-shrink: 0;
}

/* --- Filter Tabs --- */
.ops-queue__filters {
 display: flex;
 align-items: center;
 justify-content: space-between;
 margin-bottom: 16px;
 border-bottom: 1px solid #1a2035;
 padding-bottom: 12px;
}

.ops-queue__tabs {
 display: flex;
 gap: 4px;
}

.ops-queue__tab {
 font-size: 12px;
 font-weight: 500;
 color: #64748b;
 background: none;
 border: none;
 padding: 6px 14px;
 border-radius: 6px;
 cursor: pointer;
 transition: background 0.12s ease, color 0.12s ease;
}

.ops-queue__tab:hover {
 background: rgba(255, 255, 255, 0.04);
 color: #94a3b8;
}

.ops-queue__tab--active {
 background: rgba(59, 130, 246, 0.1);
 color: #3b82f6;
 font-weight: 600;
}

.ops-queue__legend {
 display: flex;
 align-items: center;
 gap: 4px;
 font-size: 11px;
 color: #64748b;
}

.ops-queue__legend-label {
 color: #64748b;
 margin-right: 4px;
}

.ops-queue__legend-fresh {
 color: #22c55e;
}

.ops-queue__legend-sep {
 color: #64748b;
 margin: 0 2px;
}

.ops-queue__legend-risk {
 color: #f59e0b;
}

.ops-queue__legend-overdue {
 color: #ef4444;
}

/* --- Table --- */
.ops-queue__table {
 width: 100%;
 border-collapse: collapse;
}

.ops-queue__table thead th {
 font-size: 10px;
 font-weight: 600;
 color: #475569;
 text-transform: uppercase;
 letter-spacing: 0.5px;
 text-align: left;
 padding: 8px 12px;
 border-bottom: 1px solid #1a2035;
}

.ops-queue__table tbody tr {
 border-bottom: 1px solid rgba(26, 32, 53, 0.5);
 transition: background 0.1s ease;
}

.ops-queue__table tbody tr:hover {
 background: rgba(255, 255, 255, 0.02);
}

.ops-queue__table tbody td {
 padding: 10px 12px;
 font-size: 13px;
 vertical-align: top;
}

/* --- Table Cells --- */
.ops-queue__complaint-id {
 font-weight: 600;
 color: #e2e8f0;
 font-size: 12px;
}

.ops-queue__complaint-desc {
 font-size: 11px;
 color: #64748b;
 margin: 2px 0 0 0;
}

.ops-queue__store-name {
 color: #3b82f6;
 font-size: 12px;
 font-weight: 500;
 cursor: pointer;
 text-decoration: none;
}

.ops-queue__store-name:hover {
 text-decoration: underline;
}

.ops-queue__store-id {
 font-size: 11px;
 color: #64748b;
 margin: 2px 0 0 0;
}

/* --- Priority Badges --- */
.ops-queue__priority {
 display: inline-flex;
 align-items: center;
 font-size: 11px;
 font-weight: 600;
 padding: 2px 8px;
 border-radius: 4px;
}

.ops-queue__priority--p1 {
 color: #ef4444;
 background: rgba(239, 68, 68, 0.1);
 border: 1px solid rgba(239, 68, 68, 0.25);
}

.ops-queue__priority--p2 {
 color: #f59e0b;
 background: rgba(245, 158, 11, 0.1);
 border: 1px solid rgba(245, 158, 11, 0.25);
}

.ops-queue__priority--p3 {
 color: #64748b;
 background: rgba(59, 130, 246, 0.08);
 border: 1px solid rgba(59, 130, 246, 0.2);
}

.ops-queue__priority--p4 {
 color: #64748b;
 background: rgba(100, 116, 139, 0.1);
 border: 1px solid rgba(100, 116, 139, 0.2);
}

/* --- Agent --- */
.ops-queue__agent--unassigned {
 color: #f59e0b;
 font-weight: 500;
}

.ops-queue__agent--assigned {
 color: #94a3b8;
}

/* --- Status --- */
.ops-queue__status {
 font-size: 12px;
 color: #94a3b8;
}

/* --- Age Colors --- */
.ops-queue__age--fresh {
 color: #22c55e;
 font-variant-numeric: tabular-nums;
}

.ops-queue__age--risk {
 color: #f59e0b;
 font-variant-numeric: tabular-nums;
}

.ops-queue__age--overdue {
 color: #ef4444;
 font-variant-numeric: tabular-nums;
}

/* --- Responsive --- */
@media (max-width: 1200px) {
 .ops-kpi-row {
 grid-template-columns: repeat(3, 1fr);
 }
